def room_paths(room, direction):
    paths = {
        "center": {"north": "armory", "south": "door"},
        "armory": {"south": "center"},
        "door": {"north": "center"},
    }
    return paths[room][direction]


def run_tests():
    assert room_paths("center", "north") == "armory"
    assert room_paths("center", "south") == "door"
    assert room_paths("armory", "south") == "center"
    assert room_paths("door", "north") == "center"
    print("All asserts passed.")


if __name__ == "__main__":
    run_tests()
